package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.role.StewardOnlyException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Waives an OPEN or PENDING claim's late charge, once: only a steward may; any other status, or a
 * claim already waived, is refused and writes nothing.
 */
public class WaiveClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, RoleRepository roles, ClaimRepository repository,
            HttpServletRequest request) throws StewardOnlyException, InvalidClaimStatusException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!Role.STEWARD.equals(role)) {
            throw new StewardOnlyException("Only a steward may waive a late charge: " + user + " is a " + role);
        }
        claim.waive();
        if (!repository.waive(claim)) throw new InvalidClaimStatusException("The claim's late charge was already waived");
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the waiver of the claim's late charge, naming the claim like every claim line. */
public class AuditClaimWaived {
    public void audit(@Val Sheet sheet, @Val Claim claim, PersonRepository people, HttpServletRequest request,
            Audit audit) {
        Person person = people.find(sheet.id(), claim.getPersonId());
        audit.record(ClaimAudit.line("CLAIM_WAIVED", sheet, Audit.user(request), person, claim));
    }
}
package net.officefloor.hq.app.claim;

/** A claim with a missing, negative or over-precise amount, or a date that is not a date. */
public class InvalidClaimException extends Exception {
    public InvalidClaimException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidClaim {
    public void handle(@Parameter InvalidClaimException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
handle:
  class: net.officefloor.hq.app.claim.HandleInvalidClaim
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A deferral needs a date to defer the claim until. */
public class ValidateDefer {
    public void validate(@RequestBody DeferRequest request, Out<Deferral> body) throws InvalidClaimException {
        String raw = request == null || request.until() == null ? "" : request.until().trim();
        try {
            body.set(new Deferral(LocalDate.parse(raw)));
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("A deferral needs a date to defer the claim until");
        }
    }
}
package net.officefloor.hq.app.claim;

/** A deferral as the screen sends it: the date (yyyy-MM-dd) to defer the claim until. */
public record DeferRequest(String until) {
}
# Defer an OPEN claim until a date after the sheet's today. A claim that is not OPEN is a 409, a
# missing date or one not after today a 400, and either writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateDefer
  govern: [ transaction ]
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
