package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The claims' shares, kept per sheet, oldest first. */
@Repository
public class ClaimShareRepository {

    private final JdbcTemplate jdbc;

    public ClaimShareRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Keep a share of the claim. */
    public void add(Claim claim, ClaimShare share) {
        jdbc.update("INSERT INTO claim_share (sheet_id, claim_id, person_id, share) VALUES (?, ?, ?, ?)",
                claim.getSheetId(), claim.getId(), share.personId(), share.share());
    }

    /** The claim's shares, oldest first. */
    public List<ClaimShare> of(Claim claim) {
        return findAll(claim.getSheetId()).getOrDefault(claim.getId(), List.of());
    }

    /** The sheet's shares by claim id, each claim's oldest first. */
    public Map<Long, List<ClaimShare>> findAll(String sheetId) {
        Map<Long, List<ClaimShare>> shares = new HashMap<>();
        jdbc.query("SELECT claim_id, person_id, share FROM claim_share WHERE sheet_id = ? ORDER BY id", (rs) -> {
            shares.computeIfAbsent(rs.getLong("claim_id"), (k) -> new ArrayList<>())
                    .add(new ClaimShare(rs.getLong("person_id"), rs.getBigDecimal("share").setScale(2)));
        }, sheetId);
        return shares;
    }

    /** The claim's shares added up: 0.00 when it has none. */
    public static BigDecimal total(List<ClaimShare> shares) {
        return shares.stream().map(ClaimShare::share).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }
}
