              />{' '}
              <select
                data-testid="claim-void-reason"
                aria-label="Void reason"
                value={voidReasons[c.id] ?? ''}
                onChange={(e) => {
                  setVoidReasons((r) => ({ ...r, [c.id]: e.target.value }));
                  setRefused((r) => (r !== null && r.id === c.id ? null : r));
