              >
                <option value="">No void reason</option>
                {voidReasonList.map((r) => (
                  <option key={r} value={r}>
                    {r}
                  </option>
                ))}
              </select>{' '}
              {ACTIONS.map(({ action, label }) => (
                <Fragment key={action}>
                  {action === 'settle' && (
                    <input
                      type="date"
                      data-testid="claim-settle-date"
                      aria-label="Settle as of"
                      value={settleOn[c.id] ?? ''}
